def solve_occ(g, color, rotate=False):
 H,W=len(g),len(g[0]); cells=[(r,c) for r in range(H) for c in range(W) if g[r][c]==color]
 r0=min(r for r,c in cells);c0=min(c for r,c in cells); shape={(r-r0,c-c0) for r,c in cells}; hh=max(r for r,c in shape)+1;ww=max(c for r,c in shape)+1
 candidates=[]
 shapes=[shape]
 if rotate:
  for k in range(1,4):
   sh=shape
   for _ in range(k): sh={(c,-r) for r,c in sh}
   minr=min(r for r,c in sh);minc=min(c for r,c in sh);shapes.append({(r-minr,c-minc) for r,c in sh})
 for sh in shapes:
  shh=max(r for r,c in sh)+1; shw=max(c for r,c in sh)+1
  for r in range(H-shh+1):
   for c in range(W-shw+1):
    if all(g[r+dr][c+dc]==0 for dr,dc in sh):candidates.append((r,c,sh))
 out={(r+dr,c+dc) for r,c,sh in candidates for dr,dc in sh}
 return out,candidates,shape
for g,o,col in [(z,zz,8)]:
 out,cands,sh=solve_occ(g,col)
 actual={(r,c) for r in range(len(g)) for c in range(len(g[0])) if g[r][c]==0 and o[r][c]==col}
 print('template',len(sh),'match count',len(cands),'union',len(out),'actual',len(actual),'miss',len(actual-out),'extra',len(out-actual))

